mapper.select:
SELECT COALESCE(SUM(spending_amount), 0)
FROM tb_trn_spending
WHERE user_id = #{userId}
  AND spending_date BETWEEN #{startDate} AND #{endDate}
  AND delete_flg = false

SELECT COALESCE(budget_amount, 0)
FROM tb_trn_budget
WHERE user_id = #{userId}
  AND EXTRACT(YEAR FROM budget_month) = #{year}
  AND EXTRACT(MONTH FROM budget_month) = #{month}
